#!/usr/bin/env node
/**
 * repair-phonics-manifests.mjs — rescue real words from corrupt manifests.
 *
 *   node scripts/repair-phonics-manifests.mjs --dry-run
 *   node scripts/repair-phonics-manifests.mjs --apply
 *
 * 24 manifests in CH01T01 were generated by a bad translation pass: the
 * Romanian name is a real word (`castel`, `cuțit`, `mașină`) but the other
 * eight locales hold the PHONICS FRAGMENT the row was originally about
 * (`-stle`, `kn-`, `ch`). They are tagged `alphabet#*` and were orphaned by the
 * LT/ST re-key, so nobody noticed.
 *
 * This script rewrites the eight broken locales with real translations and
 * retags the manifest as vocabulary. The Romanian is left untouched — it is the
 * only field that was ever right.
 *
 * Nine of the 24 are skipped: their Romanian word already exists elsewhere in
 * the dictionary under a different code.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = fileURLToPath(new URL('..', import.meta.url))
const MEDIA = join(ROOT, 'media', 'dictionary')
const SIDEBAR = join(ROOT, 'src', 'data', 'sidebars', 'library', 'dictionary', 'sidebar.json')

const apply = process.argv.includes('--apply')
const readJson = (p) => JSON.parse(readFileSync(p, 'utf-8'))

/**
 * The real translations for each corrupt manifest, keyed by its code.
 * `ro` is omitted — the manifest's own Romanian is already correct.
 */
const REPAIRS = {
  W010: { en: 'castle', de: 'Burg', ru: 'замок', it: 'castello', es: 'castillo', fr: 'château', hu: 'kastély', pt: 'castelo' },
  W013: { en: 'choir', de: 'Chor', ru: 'хор', it: 'coro', es: 'coro', fr: 'chœur', hu: 'kórus', pt: 'coro' },
  W025: { en: 'gnome', de: 'Gnom', ru: 'гном', it: 'gnomo', es: 'gnomo', fr: 'gnome', hu: 'gnóm', pt: 'gnomo' },
  W029: { en: 'half', de: 'Hälfte', ru: 'половина', it: 'metà', es: 'mitad', fr: 'moitié', hu: 'fél', pt: 'metade' },
  W034: { en: 'knife', de: 'Messer', ru: 'нож', it: 'coltello', es: 'cuchillo', fr: 'couteau', hu: 'kés', pt: 'faca' },
  W037: { en: 'car', de: 'Auto', ru: 'машина', it: 'auto', es: 'coche', fr: 'voiture', hu: 'autó', pt: 'carro' },
  W052: { en: 'ship', de: 'Schiff', ru: 'корабль', it: 'nave', es: 'barco', fr: 'navire', hu: 'hajó', pt: 'navio' },
  W053: { en: 'to sing', de: 'singen', ru: 'петь', it: 'cantare', es: 'cantar', fr: 'chanter', hu: 'énekelni', pt: 'cantar' },
  W058: { en: 'to think', de: 'denken', ru: 'думать', it: 'pensare', es: 'pensar', fr: 'penser', hu: 'gondolni', pt: 'pensar' },
  W059: { en: 'this', de: 'dieser', ru: 'этот', it: 'questo', es: 'este', fr: 'ce', hu: 'ez', pt: 'este' },
  W060: { en: 'although', de: 'obwohl', ru: 'хотя', it: 'sebbene', es: 'aunque', fr: 'bien que', hu: 'bár', pt: 'embora' },
  W061: { en: 'thought', de: 'Gedanke', ru: 'мысль', it: 'pensiero', es: 'pensamiento', fr: 'pensée', hu: 'gondolat', pt: 'pensamento' },
  W062: { en: 'through', de: 'durch', ru: 'через', it: 'attraverso', es: 'a través de', fr: 'à travers', hu: 'keresztül', pt: 'através' },
  W074: { en: 'to know', de: 'wissen', ru: 'знать', it: 'sapere', es: 'saber', fr: 'savoir', hu: 'tudni', pt: 'saber' },
  W076: { en: 'lamb', de: 'Lamm', ru: 'ягнёнок', it: 'agnello', es: 'cordero', fr: 'agneau', hu: 'bárány', pt: 'cordeiro' }
}

/** Where each rescued word belongs. */
const PLACEMENT = {
  W010: 'CH13T01', // castle → Architecture
  W013: 'CH06T06', // choir → Arts & music
  W025: 'CH12T01', // gnome → Idioms & fixed expressions
  W029: 'CH06T03', // half → Maths & measurement
  W034: 'CH02T04', // knife → Furniture & household objects
  W037: 'CH04T04', // car → Public transport
  W052: 'CH05T01', // ship → Airport & border
  W053: 'CH06T06', // to sing → Arts & music
  W058: 'CH11T07', // to think → Abstract ideas & philosophy
  W059: 'CH11T03', // this → Logical connectors
  W060: 'CH11T05', // although → Comparison & contrast
  W061: 'CH11T07', // thought → Abstract ideas & philosophy
  W062: 'CH11T03', // through → Logical connectors
  W074: 'CH11T07', // to know → Abstract ideas & philosophy
  W076: 'CH08T02' // lamb → Wild animals & plants
}

function main() {
  const sidebar = readJson(SIDEBAR)
  const referenced = new Set()
  for (const section of sidebar.sections) {
    for (const topic of section.topics) for (const id of topic.items ?? []) referenced.add(id)
  }

  // Romanian term → owning code, so a rescue cannot duplicate a word.
  const existingRo = new Map()
  for (const section of sidebar.sections) {
    for (const topic of section.topics) {
      const dir = join(MEDIA, section.code, topic.code)
      if (!existsSync(dir)) continue
      for (const entry of readdirSyncSafe(dir)) {
        const file = join(dir, entry, 'item.json')
        if (!existsSync(file)) continue
        const manifest = readJson(file)
        if (!referenced.has(manifest.code)) continue
        const ro = manifest.locales?.ro?.name?.toLowerCase()
        if (ro) existingRo.set(ro, `${topic.code}/${manifest.code}`)
      }
    }
  }

  const repaired = []
  const skipped = []

  for (const [code, names] of Object.entries(REPAIRS)) {
    const file = join(MEDIA, 'CH01', 'CH01T01', code, 'item.json')
    if (!existsSync(file)) {
      skipped.push(`${code} (manifest missing)`)
      continue
    }
    const manifest = readJson(file)
    const ro = manifest.locales?.ro?.name ?? ''
    if (existingRo.has(ro.toLowerCase())) {
      skipped.push(`${code} ${ro} (already ${existingRo.get(ro.toLowerCase())})`)
      continue
    }
    const target = PLACEMENT[code]
    const section = sidebar.sections.find((s) => s.topics.some((t) => t.code === target))
    const topic = section?.topics.find((t) => t.code === target)
    if (!topic) {
      skipped.push(`${code} ${ro} (unknown topic ${target})`)
      continue
    }

    // Rewrite the eight broken locales; keep the Romanian exactly as it is.
    for (const [locale, name] of Object.entries(names)) {
      manifest.locales[locale] = { ...(manifest.locales[locale] ?? {}), name }
    }
    manifest.tags = [`vocabulary#${target}`]
    manifest.topic = target
    manifest.chapter = section.code
    manifest.entity_id = `${target}:${code}`

    if (apply) writeFileSync(file, JSON.stringify(manifest, null, 2) + '\n')
    if (!topic.items.includes(code)) topic.items.push(code)
    existingRo.set(ro.toLowerCase(), `${target}/${code}`)
    repaired.push(`${code} ${ro} → ${target} (en: ${names.en})`)
  }

  console.log(`repair: ${repaired.length} manifest(s) rescued`)
  for (const line of repaired) console.log('  +', line)
  if (skipped.length) {
    console.log(`repair: ${skipped.length} skipped`)
    for (const line of skipped) console.log('  =', line)
  }

  if (!apply) {
    console.log('repair: dry run — nothing written')
    return
  }
  writeFileSync(SIDEBAR, JSON.stringify(sidebar, null, 2) + '\n')
  console.log('repair: sidebar written')
}

/** Directory entries, or [] when the folder is absent. */
function readdirSyncSafe(dir) {
  try {
    return readdirSync(dir, { withFileTypes: true })
      .filter((e) => e.isDirectory() && e.name !== 'sound')
      .map((e) => e.name)
  } catch {
    return []
  }
}

import { readdirSync } from 'node:fs'

main()
